/**
 * lib/assetProvenance — B-KID-153: the asset provenance register's shape and
 * its ONE pure check (extends the B-BOOK-27 plate contract, platePolicy.ts,
 * from plates to every final asset). The register is
 * src/content/assetProvenance.json, generated by scripts/asset-provenance.mjs
 * from the provenance the tree already records; the build check is
 * assetProvenance.test.ts over every file under public/visuals and
 * public/audio/kid.
 *
 * A row per rendered shot and per song or sound: where its provenance is
 * recorded, where the generating model is named (never the identifier
 * itself), the prompt hash, the reference, the human contribution, the
 * licence, the approvals and the AI-authorship record (US Copyright Office
 * guidance: say what is AI-generated, describe the human authorship, exclude
 * the AI material from any claim). A null field is a recorded gap, not a
 * pass: licence and per-plate model/prompt are owed by the owner.
 *
 * Pure: no fs; the test hands it the file list and the hashes.
 */

export type AssetKind = "shot" | "song" | "sound";

export interface AssetProvenanceRow {
  /** Path under public/ ("visuals/…", "audio/kid/…"). */
  asset: string;
  /** sha256 of the shipped file: a swapped file is not the registered one. */
  sha256: string;
  kind: AssetKind;
  /** The record this row is joined from ("docs/design/x.json#id", a plate geometry entry). */
  source: string;
  /** Where the generating model is named; null = not recorded in the tree. */
  model: { recordedIn: string } | null;
  /** sha256 of the prompt text as recorded at the source; null = not in the public tree. */
  promptHash: string | null;
  /** The reference input: its hash, "none" (recorded as a new original), or null (not recorded). */
  reference: { hash: string } | "none" | null;
  /** sha256 of the preserved original master, when recorded. */
  master: string | null;
  /** The human contribution, in words. */
  human: string;
  /** null = owed (the owner confirms the terms). */
  licence: string | null;
  approvals: { by: string; what: string }[];
  /** The AI-authorship record. */
  aiAuthorship: { aiGenerated: boolean; humanAuthorship: string; claimExcludes: string };
}

export interface AssetProvenanceRegister {
  schema: 1;
  rows: AssetProvenanceRow[];
  /** FROZEN baseline: shipped assets with no recorded provenance. May only shrink. */
  unregistered: string[];
}

/** A model identifier never sits in the register itself (the row points at its record). */
export const MODEL_NAME = /\b(gemini|imagen|gpt|dall-?e|midjourney|flux|stable[- ]?diffusion|sdxl|claude|veo|lyria|chirp|eleven ?labs|suno)\b/i;

/** Schema findings for one row (empty = complete as a row; nulls are recorded gaps). */
export function rowFindings(row: AssetProvenanceRow): string[] {
  const out: string[] = [];
  const at = row?.asset ?? "(no asset)";
  const str = (v: unknown) => typeof v === "string" && v.trim().length > 0;
  const hex = (v: unknown) => typeof v === "string" && /^[0-9a-f]{64}$/.test(v);
  if (!str(row.asset) || !/^(visuals|audio\/kid)\//.test(row.asset)) out.push(`${at}: not an asset path under visuals/ or audio/kid/`);
  if (!hex(row.sha256)) out.push(`${at}: no file hash`);
  if (!["shot", "song", "sound"].includes(row.kind)) out.push(`${at}: kind is not shot, song or sound`);
  if (!str(row.source)) out.push(`${at}: no source record`);
  if (row.model !== null && !str(row.model?.recordedIn)) out.push(`${at}: model must point at its record or be null`);
  if (row.promptHash !== null && !hex(row.promptHash)) out.push(`${at}: prompt hash is not a sha256`);
  if (row.reference !== null && row.reference !== "none" && !hex(row.reference?.hash)) out.push(`${at}: reference is not a hash, "none" or null`);
  if (row.master !== null && !hex(row.master)) out.push(`${at}: master is not a sha256`);
  if (!str(row.human)) out.push(`${at}: no human contribution recorded`);
  if (row.licence !== null && !str(row.licence)) out.push(`${at}: licence must be text or null`);
  if (!Array.isArray(row.approvals) || row.approvals.some((a) => !str(a?.by) || !str(a?.what))) out.push(`${at}: approvals are not a list of {by, what}`);
  const ai = row.aiAuthorship;
  if (!ai || typeof ai.aiGenerated !== "boolean" || !str(ai.humanAuthorship) || !str(ai.claimExcludes)) out.push(`${at}: no AI-authorship record`);
  if (MODEL_NAME.test(JSON.stringify(row))) out.push(`${at}: a model identifier is copied into the row`);
  return out;
}

/**
 * The build check: every shipped asset resolves to a row whose hash matches,
 * or is on the frozen baseline; the baseline names only shipped assets with no
 * row; every row is complete and shipped. `hashOf` reads a file's sha256.
 */
export function provenanceFindings(files: readonly string[], hashOf: (asset: string) => string, register: Pick<AssetProvenanceRegister, "rows" | "unregistered">): string[] {
  const out: string[] = [];
  const rows = new Map<string, AssetProvenanceRow>();
  for (const row of register.rows) {
    if (rows.has(row.asset)) out.push(`${row.asset}: registered twice`);
    rows.set(row.asset, row);
    out.push(...rowFindings(row));
  }
  const baseline = new Set(register.unregistered);
  const onDisk = new Set(files);
  for (const f of files) {
    const row = rows.get(f);
    if (row) {
      if (row.sha256 !== hashOf(f)) out.push(`${f}: the file is not the registered one (hash changed): re-register it`);
    } else if (!baseline.has(f)) out.push(`${f}: an unregistered asset (record its provenance, then run scripts/asset-provenance.mjs --write)`);
  }
  for (const asset of rows.keys()) if (!onDisk.has(asset)) out.push(`${asset}: a register row for an asset that is not shipped`);
  for (const b of baseline) {
    if (rows.has(b)) out.push(`${b}: registered now: remove it from the frozen baseline`);
    else if (!onDisk.has(b)) out.push(`${b}: gone: remove it from the frozen baseline`);
  }
  return out;
}
